-- Databasdump för aktieanalys.
-- Sorterad med flit: det gör filen deterministisk, så att
-- git kan lagra varje vecka som en liten delta.
-- Återskapa med: python -m aktieanalys aterskapa-databas
PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE bolagsmeta (
    ticker        TEXT NOT NULL,
    datum         TEXT NOT NULL,
    namn          TEXT,
    valuta        TEXT,
    rapportvaluta TEXT,
    PRIMARY KEY (ticker, datum)
);
CREATE TABLE fundamenta (
    ticker     TEXT NOT NULL,
    datum      TEXT NOT NULL,
    falt       TEXT NOT NULL,
    varde      REAL,
    varde_json TEXT,
    kalla      TEXT,
    PRIMARY KEY (ticker, datum, falt)
);
CREATE TABLE hamtlogg (
    id          INTEGER PRIMARY KEY AUTOINCREMENT,
    ticker      TEXT NOT NULL,
    datum       TEXT NOT NULL,
    tidpunkt    TEXT NOT NULL,
    kalla       TEXT NOT NULL,
    status      TEXT NOT NULL,
    antal_falt  INTEGER,
    meddelande  TEXT
);
CREATE TABLE kurser (
    ticker     TEXT NOT NULL,
    datum      TEXT NOT NULL,
    stangning  REAL NOT NULL,
    volym      REAL,
    PRIMARY KEY (ticker, datum)
);
CREATE TABLE saknat (
    ticker TEXT NOT NULL,
    datum  TEXT NOT NULL,
    falt   TEXT NOT NULL,
    orsak  TEXT NOT NULL,
    PRIMARY KEY (ticker, datum, falt)
);
CREATE TABLE veckopoang (
    datum              TEXT NOT NULL,
    ticker             TEXT NOT NULL,
    kategori           TEXT NOT NULL,
    poang_kvantitativ  REAL,
    poang_slutlig      REAL,
    placering          INTEGER,
    ar_innehav         INTEGER NOT NULL DEFAULT 0,
    justering          REAL NOT NULL DEFAULT 0,
    PRIMARY KEY (datum, ticker)
);
CREATE INDEX ix_fundamenta_falt ON fundamenta (ticker, falt, datum);
CREATE INDEX ix_hamtlogg_datum ON hamtlogg (datum);
CREATE INDEX ix_veckopoang ON veckopoang (kategori, datum);
COMMIT;
